sql.29cd9c3b7b:
select (
    select coalesce(json_agg(json_build_array(
      windowed.role, windowed.count, windowed.rank, windowed.id, windowed.name,
      windowed.category, windowed.status, case when ("file"."id" is not null and "file"."original_missing_since" is null) then "file"."file_name" end, "file"."version",
      "file"."variant_key"
    ) order by windowed.rank), '[]')
    from (
      select flagged.*,
        array_agg(flagged.rank) filter (where flagged.chosen) over (partition by flagged.role) as chosen_ranks
      from (
        select ranked.*, exists (select from unnest(array[]::int[], array[]::text[]) as chosen (id, role) where chosen.id = ranked.id and chosen.role = ranked.role) as chosen
        from (
          select "garment"."id" as id, "garment"."name" as name,
            "garment"."category" as category, "garment"."status" as status,
            "garment"."photo_id" as photo_id, case when "garment"."category" = $1 then $2 when "garment"."category" = $3 then $4 when "garment"."category" = $5 then $6 when "garment"."category" = $7 then $8 when "garment"."category" = $9 then $10 when "garment"."category" = $11 then $12 when "garment"."category" = $13 then $14 else 'none' end as role,
            (row_number() over (partition by case when "garment"."category" = $15 then $16 when "garment"."category" = $17 then $18 when "garment"."category" = $19 then $20 when "garment"."category" = $21 then $22 when "garment"."category" = $23 then $24 when "garment"."category" = $25 then $26 when "garment"."category" = $27 then $28 else 'none' end order by "garment"."id" desc))::int as rank,
            (count(*) over (partition by case when "garment"."category" = $29 then $30 when "garment"."category" = $31 then $32 when "garment"."category" = $33 then $34 when "garment"."category" = $35 then $36 when "garment"."category" = $37 then $38 when "garment"."category" = $39 then $40 when "garment"."category" = $41 then $42 else 'none' end))::int as count
          from "garment"
          where ("garment"."owner_id" = $43 and "garment"."status" = $44)
        ) ranked
      ) flagged
    ) windowed
    left join "file" on "file"."id" = windowed.photo_id
    where windowed.rank <= $45
      or exists (select from unnest(windowed.chosen_ranks) as near (rank) where abs(windowed.rank - near.rank) <= $46)
  ) as "windows", (
    select coalesce(
      json_agg(
        json_build_object('id', "capsule"."id", 'name', "capsule"."name")
        order by lower("capsule"."name") asc, "capsule"."id" asc
      ),
      '[]'
    )
    from "capsule"
    where "capsule"."owner_id" = $47
  ) as "capsules", (
    select coalesce(json_agg(kinds), '[]')
    from (
      select distinct "garment"."category" as category, "garment"."type" as type
      from "garment"
      where ("garment"."owner_id" = $48 and "garment"."status" = $49)
    ) kinds
  ) as "closetKinds"

